/* portrait framing: pull every camera back for the vinyl cast */
(() => { const K = 2.25; const sc1 = (c) => { c[2] += 2.0; c[4] *= K; c[5] *= K; c[6] *= K; }; for (const id in SC) { const c = SC[id].cam; if (!c) continue; if (typeof c[0] === 'number') sc1(c); else c.forEach(sc1); } })();
/* readability: figures turned fully sideways (f ±90..±110) face the camera a little more */
(() => { const FIG = new Set(['john', 'john2', 'johnH', 'johnH2', 'iosef', 'viggo', 'abram', 'aure', 'winston', 'perk', 'santino', 'gianna', 'cassian', 'bking', 'sofia', 'elder', 'adj', 'zero', 'big', 'marquis', 'caine', 'nobody', 'killa', 'chidi', 'berr', 'g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'a1', 'a2', 'a3']);
  for (const id in SC) for (const k in (SC[id].A || {})) { const a = SC[id].A[k]; if (!a || !FIG.has(k) || typeof a.f !== 'number' || a.on) continue; if (a.f >= 80 && a.f <= 120) a.f = 62; else if (a.f <= -80 && a.f >= -120) a.f = -62; } })();
EP.light = 1.6;
